import{_ as e,o as s,c as i,O as t}from"./chunks/framework.loC67i-H.js";const c=JSON.parse('{"title":"Handbooks","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/handbooks.md","filePath":"documentation/handbooks.md","lastUpdated":1794218615000}'),o={name:"documentation/handbooks.md"};function n(r,a,h,d,l,p){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="handbooks" tabindex="-1">Handbooks <a class="header-anchor" href="#handbooks" aria-label="Permalink to &quot;Handbooks&quot;">​</a></h1><p>A handbook is a static site that a team writes in Git and installs in Naira: onboarding, engineering standards, runbooks, approved patterns. The portal lists every installed handbook in the <strong>Docs</strong> group of the sidebar and opens it inside the portal. Naira does not edit or index handbooks, and a handbook&#39;s pages never become catalog properties. The team that owns a handbook changes it through its own repository and review rules.</p><h2 id="reading-a-handbook" tabindex="-1">Reading a handbook <a class="header-anchor" href="#reading-a-handbook" aria-label="Permalink to &quot;Reading a handbook&quot;">​</a></h2><p>Open a handbook from the Docs group. It opens at the portal address <code>/&lt;id&gt;</code>, and links inside the handbook move the portal address with them, so a page can be shared by its link. The footer of every page names the owner, the source repository, the version and the build time. Every signed-in user can open every installed handbook.</p><h2 id="writing-a-handbook" tabindex="-1">Writing a handbook <a class="header-anchor" href="#writing-a-handbook" aria-label="Permalink to &quot;Writing a handbook&quot;">​</a></h2><p>A handbook lives in its owner&#39;s repository. The <a href="https://github.com/naira-project/naira/tree/main/handbook/starter" target="_blank" rel="noreferrer">handbook starter</a> is a <a href="https://vitepress.dev" target="_blank" rel="noreferrer">VitePress</a> site: pages are Markdown files, and a file&#39;s path is its address. The starter also defines the image contract <code>naira.handbook/v1alpha1</code>, which an image built with another generator can follow as well.</p><p>The <a href="https://github.com/naira-project/example-handbook" target="_blank" rel="noreferrer">example handbook</a> is a complete handbook repository built from the starter. To start your own:</p><ol><li>Copy the example repository, or fork it.</li><li>In <code>package.json</code>, set <code>name</code> (the handbook id, a DNS label of at most 42 characters), <code>naira.title</code>, <code>naira.owner</code>, <code>repository</code> and <code>bugs</code>.</li><li>Set the same id as <code>handbook-id</code> in <code>.github/workflows/handbook-build.yml</code>.</li><li>Replace the pages in <code>docs/</code> and the sidebar in <code>.vitepress/config.mts</code>.</li><li>Push to <code>main</code>.</li></ol><p>The workflow calls <code>reusable-handbook-build.yml</code> from <a href="https://github.com/naira-project/naira-github-workflows" target="_blank" rel="noreferrer">naira-github-workflows</a>. It builds the image, signs it with Cosign (keyless), attests its provenance, pushes it to the GitHub container registry and checks the image&#39;s <code>naira-handbook.json</code>. The run summary shows the image reference with its digest, which is what the operator installs.</p><h2 id="installing-a-handbook" tabindex="-1">Installing a handbook <a class="header-anchor" href="#installing-a-handbook" aria-label="Permalink to &quot;Installing a handbook&quot;">​</a></h2><p>The operator adds the handbook to the Helm values. The chart takes an image only by digest and only from a registry in <code>handbookGateway.allowedRegistries</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">handbookGateway</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  domain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">handbook.naira.example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  scheme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">443</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  portalOrigin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://naira.example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allowedRegistries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ghcr.io/naira-project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">handbooks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">example</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    contract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">naira.handbook/v1alpha1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    label</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Example Handbook</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    primary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ghcr.io/naira-project/example-handbook@sha256:&lt;digest&gt;</span></span></code></pre></div><p>An upgrade is a new digest. <code>enabled: false</code> or removing the entry removes the handbook and nothing else.</p><p>Each handbook runs as its own Deployment and is served at its own address, <code>&lt;id&gt;.&lt;handbookGateway.domain&gt;</code>, behind the handbook gateway (Envoy). The gateway checks the user&#39;s Keycloak token before it serves a page and shows an &quot;unavailable&quot; page when a handbook&#39;s pods are not healthy, so one broken handbook does not affect the others or the portal. Operators provide:</p><ul><li>Wildcard DNS and a wildcard TLS certificate for <code>*.&lt;handbookGateway.domain&gt;</code>, pointing at the Service <code>handbook-gateway</code>. TLS ends in front of the gateway.</li><li>A handbook domain on the same site as the portal, for example <code>naira.example.com</code> and <code>*.handbook.naira.example.com</code>. Browsers drop the handbook&#39;s session cookie otherwise.</li></ul><h2 id="trust" tabindex="-1">Trust <a class="header-anchor" href="#trust" aria-label="Permalink to &quot;Trust&quot;">​</a></h2><p>Handbook code runs in the user&#39;s browser with the user&#39;s access token: the portal hands the token to every frame it shows, and a script in a handbook can call the catalog API as that user. Naira does not prevent this yet. Install only handbooks whose code your organisation trusts: pin them by digest, pull them from a registry you control, and verify their signature before the digest goes into your values. The chart cannot check signatures; the operator guide shows the <code>cosign verify</code> call.</p><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://github.com/naira-project/naira/blob/main/docs/handbooks.md" target="_blank" rel="noreferrer">Operator guide for handbooks</a>: DNS, TLS, the same-site rule, the local development setup and signature checks.</li><li><a href="https://github.com/naira-project/naira/blob/main/deploy/charts/naira/README.md#handbooks" target="_blank" rel="noreferrer">Chart README, Handbooks</a>: what the chart renders and every value.</li><li><a href="https://github.com/naira-project/naira/blob/main/handbook/starter/README.md" target="_blank" rel="noreferrer">Starter README</a>: the image contract, <code>naira-handbook.json</code> and the upgrade rules.</li></ul>`,19)])])}const g=e(o,[["render",n]]);export{c as __pageData,g as default};
